const ODDSPEDIA_BOOK_BLACKLIST=/(?:^|[^a-z0-9])(?:pinnacle|22bet|melbet|1xbit|betwinner|unibet|888sport|sportsbet|tab|pointsbet|barstool|wynnbet|sportybet|bet9ja|sx\s*bet|hkjc)(?:$|[^a-z0-9])/i;
