function fsFields(block){const out={};for(const part of String(block||'').split('¬')){const i=part.indexOf('÷');if(i<0)continue;const k=part.slice(0,i).replace(/^~+/,'').trim(),v=part.slice(i+1).trim();if(k)out[k]=v}return out}
function parseFlashscoreListFeed(raw){const text=String(raw||'');if(!text||text==='0'||!/[¬÷]/.test(text))return[];const out=[];let ctx={};for(const block of text.split('~')){const f=fsFields(block);if(!Object.keys(f).length)continue;if(f.ZA||f.ZE||f.ZY||f.ZC)ctx={...ctx,tournament:clean(f.ZA||f.ZE||ctx.tournament||''),country:clean(f.ZY||f.ZC||ctx.country||'')};const mid=clean(f.AA),home=clean(f.AE),away=clean(f.AF),epoch=Number(f.AD);if(!/^[A-Za-z0-9]{6,20}$/.test(mid)||!home||!away||!Number.isFinite(epoch)||epoch<=0)continue;out.push({mid,t:epoch*1000,home,away,league:ctx.tournament||'Football',country:ctx.country||''})}return out}
async function fsFeed(name){let last='';for(const base of FS_FEED_BASES){const tk='flashfeed:'+base+'|'+name;if(!transportAllowed(tk))continue;try{const r=await fetchT(`${base}/${name}`,{headers:{'x-fsign':FS_X_FSIGN,referer:'https://www.flashscore.com/',accept:'text/plain,*/*'}},7000);if(!r.ok){last=`HTTP ${r.status}`;transportMark(tk,'error',last);continue}const text=await r.text();const rows=parseFlashscoreListFeed(text);if(rows.length){transportMark(tk,'ok');return rows}last='empty feed';transportMark(tk,'empty',last)}catch(e){last=clean(e?.message||e);transportMark(tk,'error',last)}}if(last)throw Error(last);return[]}
function fsOddsItem(x){if(!x||x.active===false)return null;const value=dec(x.value);return value?{value,active:x.active!==false}:null}
function parseFlashscoreBookMarket(src,event,bookName,ahEntry,ouEntry,ts){if(!event||!in24(event.t,ts))return null;const r=rowBase(src,event.mid,event.t,event.league,event.home,event.away),b=addBook(r,bookName||'Book');
 const ah=new Map();for(const o of ahEntry?.opportunities||[]){const line=num(o?.handicap?.value),home=fsOddsItem(o?.home),away=fsOddsItem(o?.away);if(line===null||!home||!away)continue;ah.set(line,{home:home.value,away:away.value})}for(const [line,z] of ah){addBet(b,'AH',`Home ${line}`,z.home);addBet(b,'AH',`Away ${line===0?0:-line}`,z.away)}
 const ou=new Map();for(const o of ouEntry?.opportunities||[]){const line=Math.abs(num(o?.handicap?.value)??NaN),over=fsOddsItem(o?.over),under=fsOddsItem(o?.under);if(!Number.isFinite(line)||line<=0||!over||!under)continue;ou.set(line,{over:over.value,under:under.value})}for(const [line,z] of ou){addBet(b,'OU',`Over ${line}`,z.over);addBet(b,'OU',`Under ${line}`,z.under)}
 return validRow(r)?r:null}
function fsMenuBooks(j){const arr=j?.data?.getPrematchOddsBettingTypeMenu?.settings?.bookmakers||[],out=[];for(const x of arr){const b=x?.bookmaker||x;if(b?.id==null)continue;const id=String(b.id),name=clean(b.name)||`Book ${id}`;if(!out.some(y=>y.id===id))out.push({id,name})}return out}
async function fsMenu(eventId){const url=`${FS_ODDS_BASE}?_hash=pobtm&eventId=${encodeURIComponent(eventId)}&projectId=2&geoIpCode=${FS_GEO.code}&geoIpSubdivisionCode=${FS_GEO.sub}`;const j=await getJ(url,{headers:{referer:'https://www.flashscore.com/','x-fsign':FS_X_FSIGN,accept:'application/json'}},8000);return fsMenuBooks(j)}
async function fsBookMarket(eventId,bookId,betType){const url=`${FS_ODDS_BASE}?_hash=ope2&eventId=${encodeURIComponent(eventId)}&bookmakerId=${encodeURIComponent(bookId)}&betType=${betType}&betScope=FULL_TIME`;const j=await getJ(url,{headers:{referer:'https://www.flashscore.com/','x-fsign':FS_X_FSIGN,accept:'application/json'}},8000);return j?.data?.findPrematchOddsForBookmaker||null}
async function sourceFlashscore(ts){return cached('S16',ts,async()=>{const probes=await Promise.allSettled(FS_FIXTURE_SUFFIXES.map(x=>fsFeed(`f_1_-1_${x}_en_2`))),ev=[];let ok=0,last='';for(const z of probes){if(z.status==='fulfilled'){ok++;ev.push(...z.value)}else last=clean(z.reason?.message||z.reason)}if(!ok&&last)throw Error(last);const uniq=[...new Map(ev.filter(x=>in24(x.t,ts)).map(x=>[x.mid,x])).values()].sort((a,b)=>a.t-b.t);
 const rows=await poolMap(uniq,3,async e=>{let books=[];try{books=(await fsMenu(e.mid)).slice(0,3)}catch{}if(books.length<2)return null;const br=await poolMap(books,2,async bk=>{const got=await Promise.allSettled([fsBookMarket(e.mid,bk.id,'ASIAN_HANDICAP'),fsBookMarket(e.mid,bk.id,'OVER_UNDER')]);const ah=got[0].status==='fulfilled'?got[0].value:null,ou=got[1].status==='fulfilled'?got[1].value:null;return parseFlashscoreBookMarket('S16',e,bk.name,ah,ou,ts)});const merged=mergeRows(br);return merged[0]||null});return mergeRows(rows)})}


function stakeLine(m,o){
 const spec=clean(o?.specifiers??m?.specifiers??'');
 let mm=spec.match(/(?:^|[|;,])\s*(?:total|hcp|handicap)=([+-]?\d+(?:\.\d+)?)/i);
 return lineFrom(o?.line,o?.handicap,o?.points,o?.total,m?.line,m?.handicap,m?.points,m?.total,mm?.[1],o?.name,o?.label);
}
function parseStakeData(src,data,ts){
 const raw=Array.isArray(data)?data:(data?.events||data?.data?.events||data?.data||[]),out=[];
 for(const e of Array.isArray(raw)?raw:[]){
  const t=parseTs(e?.startTime??e?.start_time??e?.scheduledAt??e?.date);if(!in24(t,ts))continue;
  let h=clean(e?.homeTeam?.name??e?.home_team?.name??e?.homeTeamName),a=clean(e?.awayTeam?.name??e?.away_team?.name??e?.awayTeamName);
  if(!h||!a){[h,a]=splitTeams(clean(e?.name??e?.eventName))}if(!h||!a)continue;
  const r=rowBase(src,e?.id??e?.eventId??`${norm(h)}_${norm(a)}_${t}`,t,clean(e?.competition?.name??e?.league?.name??'Football'),h,a),b=addBook(r,'Stake');
  for(const m of e?.markets||[]){
   const key=clean(m?.key??m?.marketKey??m?.type).toLowerCase(),outs=Array.isArray(m?.outcomes)?m.outcomes:[];
   if(key==='asian_handicap'){
    const H=[],A=[];
    for(const o of outs){
     const odd=dec(o?.price??o?.odds??o?.decimalOdds),line=stakeLine(m,o),lab=clean(o?.name??o?.label??o?.selectionName),nl=norm(lab);
     if(!odd||line===null)continue;
     let side='';if(/^1$|^home$/i.test(lab)||teamMatch(lab,h)||nl.startsWith(norm(h)))side='H';else if(/^2$|^away$/i.test(lab)||teamMatch(lab,a)||nl.startsWith(norm(a)))side='A';
     if(side==='H')H.push({line,odd});else if(side==='A')A.push({line,odd});
    }
    for(const x of H)for(const y of A)if(Math.abs(x.line+y.line)<1e-8){addBet(b,'AH',`Home ${x.line}`,x.odd);addBet(b,'AH',`Away ${y.line}`,y.odd)}
   }else if(key==='totals'){
    const by=new Map();
    for(const o of outs){const odd=dec(o?.price??o?.odds??o?.decimalOdds),line=stakeLine(m,o),lab=clean(o?.name??o?.label??o?.selectionName).toLowerCase();if(!odd||line===null)continue;const z=by.get(Math.abs(line))||{};if(/\bover\b/.test(lab))z.over=odd;else if(/\bunder\b/.test(lab))z.under=odd;by.set(Math.abs(line),z)}
    for(const [line,z] of by)if(z.over&&z.under){addBet(b,'OU',`Over ${line}`,z.over);addBet(b,'OU',`Under ${line}`,z.under)}
   }
  }
  if(validRow(r))out.push(r)
 }
 return mergeRows(out)
}
