 const h=clean(seed?.teamOneName),a=clean(seed?.teamTwoName);if(!h||!a)return null;
 const r=rowBase('S35',seed?.sportXeventId||seed?.eventId||`${norm(h)}_${norm(a)}_${t}`,t,clean(seed?.leagueLabel||'SX Bet Soccer'),h,a),b=addBook(r,'SX Bet');
