  try{const j=await getJ(`${SXBET_BASE}${path}?marketHash=${encodeURIComponent(hash)}`,{headers:{accept:'application/json'}},4200),pair=sxBestPair(j);if(pair[0]>1&&pair[1]>1)return pair}catch{}
