// OddStorm: provider-specific bookmaker-comparison parser.
// Discovery comes from /asianodds/, which exposes upcoming FT AH + totals lines.
// For a selected balanced line we fetch the line-comparison pages and preserve
// each underlying bookmaker name, so this wrapper cannot manufacture consensus.
const ODDSTORM_BASE='https://www.oddstorm.com';
const ODDSTORM_MONTHS={january:0,february:1,march:2,april:3,may:4,june:5,july:6,august:7,september:8,october:9,november:10,december:11};
function oddstormDecode(v){return clean(String(v??'').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"').replace(/&#39;|&apos;/gi,"'").replace(/&ndash;|&#8211;/gi,'–').replace(/&mdash;|&#8212;/gi,'—').replace(/&minus;|&#8722;/gi,'-').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>'))}
