function tzLocalUtc(y,m,d,hh,mm,tz='Europe/London'){let t=Date.UTC(y,m,d,hh,mm,0),fmt=new Intl.DateTimeFormat('en-GB',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});for(let i=0;i<3;i++){const p=Object.fromEntries(fmt.formatToParts(new Date(t)).filter(x=>x.type!=='literal').map(x=>[x.type,x.value])),shown=Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute);t-=shown-Date.UTC(y,m,d,hh,mm)}return t}
function oddstormUKTime(date,time){if(!date)return null;const m=clean(time).match(/^(\d{1,2}):(\d{2})$/);if(!m)return null;return tzLocalUtc(date.y,date.m,date.d,+m[1],+m[2],'Europe/London')}
function oddstormNum(v){const s=clean(v).replace(/[−–—]/g,'-');if(!s||s==='-'||s==='–')return null;const n=Number(s);return Number.isFinite(n)?n:null}
