 const rows=await poolMap(events,8,async e=>{try{const [ah,ou]=await Promise.all([
  getText(`${ODDSTORM_BASE}${e.href}/asian-handicap?h=${encodeURIComponent(e.ahLine)}`,{headers:{accept:'text/html,*/*',referer:`${ODDSTORM_BASE}${e.href}`}},4400),
  getText(`${ODDSTORM_BASE}${e.href}/over-under?h=${encodeURIComponent(e.ouLine)}`,{headers:{accept:'text/html,*/*',referer:`${ODDSTORM_BASE}${e.href}`}},4400)
 ]);return parseOddstormLinePages(e,ah,ou,ts)}catch{return null}});
