const ODDSKO_BASE='https://oddsko.com';
function oddskoDecode(v){return clean(String(v??'').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"').replace(/&#39;|&apos;/gi,"'").replace(/&ndash;|&#8211;/gi,'–').replace(/&mdash;|&#8212;/gi,'—').replace(/&minus;|&#8722;/gi,'-').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>'))}
