function betkingPlain(html){return clean(String(html||'').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,' ').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,' ').replace(/<br\s*\/?>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/&minus;|&#8722;|&ndash;|&#8211;|&mdash;|&#8212;/gi,'-').replace(/\s+/g,' '))}
function betkingBest(xs,isOU=false){const q=(xs||[]).filter(x=>Number.isFinite(x.line)&&(!isOU||x.line>0)&&x.left>=1.55&&x.left<=2.45&&x.right>=1.55&&x.right<=2.45);q.sort((a,b)=>Math.abs((a.left+a.right)-4)-Math.abs((b.left+b.right)-4)||Math.abs(a.left-a.right)-Math.abs(b.left-b.right)||Math.abs(a.line)-Math.abs(b.line));return q[0]||null}
function betkingMetaFromHref(href){let u;try{u=new URL(String(href||''),BETKING_BASE)}catch{return null}const m=u.pathname.match(/\/sports\/football\/[^/]+\/[^/]+\/(\d+)\/([^/?#]+)/i);if(!m)return null;return{id:m[1],slug:decodeURIComponent(m[2])}}
function betkingDiscover(html,ts){const out=[],seen=new Set(),src=String(html||'');for(const m of src.matchAll(/href=["']([^"']*\/en-ng\/sports\/football\/[^"']+\/\d+\/[^"'?#]+)[^"']*["']/gi)){let href=m[1].replace(/&amp;/g,'&'),meta=betkingMetaFromHref(href);if(!meta||seen.has(meta.id))continue;const at=m.index||0,ctx=src.slice(Math.max(0,at-1200),Math.min(src.length,at+1800)),txt=betkingPlain(ctx);let t=null;for(const z of ctx.matchAll(/20\d\d-\d\d-\d\dT\d\d:\d\d(?::\d\d(?:\.\d+)?)?Z/g)){const q=parseTs(z[0]);if(in24(q,ts)){t=q;break}}if(!t){const dm=txt.match(/\b(\d{1,2})[\/-](\d{1,2})[\/-](20\d{2})\s+(\d{1,2}):(\d{2})\b/);if(dm)t=Date.UTC(+dm[3],+dm[2]-1,+dm[1],+dm[4],+dm[5])-60*60*1000}let home='',away='';const a=txt.match(/([A-Za-z0-9À-ÿ .&'()/-]{2,55})\s+(?:vs?\.?|v)\s+([A-Za-z0-9À-ÿ .&'()/-]{2,55})/i);if(a){home=clean(a[1]).split(/\s{2,}/).pop();away=clean(a[2]).split(/\s{2,}/)[0]}seen.add(meta.id);out.push({href:new URL(href,BETKING_BASE).pathname,id:meta.id,home,away,t})}return out}
function parseBetKingPage(html,meta,ts){const text=betkingPlain(html),id=meta?.id||betkingMetaFromHref(meta?.href)?.id||'',slug=betkingMetaFromHref(meta?.href)?.slug||'';let home=clean(meta?.home),away=clean(meta?.away);if(!home||!away){const title=text.match(/\b([A-Za-z0-9À-ÿ .&'()-]{2,55})\s+(?:vs?\.?|v)\s+([A-Za-z0-9À-ÿ .&'()-]{2,55})\b/i);if(title){home=clean(title[1]);away=clean(title[2])}}if((!home||!away)&&slug){const bits=slug.split(/-v(?:s)?-/i);if(bits.length===2){home=clean(bits[0].replace(/-/g,' '));away=clean(bits[1].replace(/-/g,' '))}}let t=Number(meta?.t)||null;if(!in24(t,ts)){for(const z of String(html||'').matchAll(/20\d\d-\d\d-\d\dT\d\d:\d\d(?::\d\d(?:\.\d+)?)?Z/g)){const q=parseTs(z[0]);if(in24(q,ts)){t=q;break}}}if(!home||!away||!in24(t,ts))return null;
 const ah=[];for(const m of text.matchAll(/Asian Handicap\s*([+-]?\d+(?:\.\d+)?)\s+1\s*AH\s+(\d+(?:\.\d+)?)\s+2\s*AH\s+(\d+(?:\.\d+)?)/gi)){const pre=text.slice(Math.max(0,(m.index||0)-28),m.index||0);if(/half|1st|2nd|first|second/i.test(pre))continue;const line=Number(m[1]),lo=dec(m[2]),ro=dec(m[3]);if(Number.isFinite(line)&&lo&&ro)ah.push({line,left:lo,right:ro})}
 let ft=text,teamCut=Infinity;const ftAnchor=Math.max(0,text.search(/\bTotal Goals\b\s+Over\b/i));for(const nm of [home,away]){if(!nm)continue;const i=text.toLowerCase().indexOf(`${nm.toLowerCase()} total goals`,ftAnchor+24);if(i>=0)teamCut=Math.min(teamCut,i)}if(Number.isFinite(teamCut))ft=text.slice(0,teamCut);const mainOU=(ft.match(/\bTotal Goals\b[\s\S]{0,180}?\bOver\s+(\d+(?:\.\d+)?)\s+\bUnder\s+(\d+(?:\.\d+)?)/i)||[]),mainOver=dec(mainOU[1]),mainUnder=dec(mainOU[2]),ou=[];const ladder=(ft.match(/\bTotal Goals\b\s+Over\s+Under\s+([\s\S]{1,900})$/i)||[])[1]||'';for(const m of ladder.matchAll(/\b(\d+(?:\.\d+)?)\s+(\d+(?:\.\d+)?)\s+(\d+(?:\.\d+)?)/g)){const line=Number(m[1]),lo=dec(m[2]),ro=dec(m[3]);if(line>=0.5&&line<=8&&lo&&ro)ou.push({line,left:lo,right:ro})}
 const hb=betkingBest(ah,false);let ob=null;if(mainOver&&mainUnder)ob=ou.find(x=>Math.abs(x.left-mainOver)<0.015&&Math.abs(x.right-mainUnder)<0.015)||null;if(!ob)ob=betkingBest(ou,true);if(!hb||!ob)return null;const r=rowBase('S47',id||`${norm(home)}_${norm(away)}_${t}`,t,'BetKing Football',home,away),b=addBook(r,'BetKing');addBet(b,'AH',`Home ${hb.line}`,hb.left);addBet(b,'AH',`Away ${-hb.line}`,hb.right);addBet(b,'OU',`Over ${ob.line}`,ob.left);addBet(b,'OU',`Under ${ob.line}`,ob.right);return validRow(r)?r:null}
async function sourceBetKing(ts){return cached('S47',ts,async()=>{const hdr={accept:'text/html,*/*',referer:`${BETKING_BASE}/en-ng/`,'accept-language':'en-NG,en;q=0.9'},[landing,schedule]=await Promise.all([getText(BETKING_FOOTBALL,{headers:hdr},5200),sourceGoaloo(ts).catch(()=>[])]),items=betkingDiscover(landing,ts);for(const x of items){if(x.home&&x.away&&in24(x.t,ts))continue;const slug=norm(betkingMetaFromHref(x.href)?.slug||'');for(const r of schedule||[]){const h=clean(r?.f?.teams?.home?.name),a=clean(r?.f?.teams?.away?.name),t=parseTs(r?.f?.fixture?.date);if(!h||!a||!in24(t,ts))continue;if(slug.includes(norm(h))&&slug.includes(norm(a))){x.home=h;x.away=a;x.t=t;break}}}const seeds=items.filter(x=>x.home&&x.away&&in24(x.t,ts)).slice(0,42),rows=await poolMap(seeds,9,async x=>{try{return parseBetKingPage(await getText(`${BETKING_BASE}${x.href}`,{headers:hdr},4200),x,ts)}catch{return null}});return mergeRows(rows.filter(Boolean))})}


// NowGoal Pro: current football board exposes pre-match Asian handicap and total in the
// same row. The parser accepts only rows explicitly marked as not started ("-") and
// normalizes Indonesian/HK-style prices through the shared decimal converter.
const NOWGOALPRO_BASE='https://www.nowgoalpro.com/';
function ngpPlain(v){return clean(String(v||'').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,' ').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,' ').replace(/<br\s*\/?>/gi,' | ').replace(/<[^>]+>/g,' ').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/&minus;|&#8722;|&ndash;|&#8211;|&mdash;|&#8212;/gi,'-').replace(/\s+/g,' '))}
function ngpLine(v){let q=clean(v).replace(/[−–—]/g,'-').replace(/\s+/g,' ');if(!q)return NaN;let sign=1;if(q[0]==='+')q=q.slice(1);else if(q[0]==='-'){sign=-1;q=q.slice(1)}const mix=q.match(/^(\d+)\s+(\d+)\/(\d+)$/);if(mix)return sign*(Number(mix[1])+Number(mix[2])/Number(mix[3]));const frac=q.match(/^(\d+)\/(\d+)$/);if(frac)return sign*Number(frac[1])/Number(frac[2]);const n=Number(q);return Number.isFinite(n)?sign*n:NaN}
function ngpTime(v,ts){const m=clean(v).match(/\b(\d{1,2}):(\d{2})\s+(\d{1,2})-(\d{1,2})\b/);if(!m)return null;const base=new Date(ts),y=base.getUTCFullYear(),t=Date.UTC(y,+m[4]-1,+m[3],+m[1]-7,+m[2]);return t<ts-12*3600000?Date.UTC(y+1,+m[4]-1,+m[3],+m[1]-7,+m[2]):t}
function ngpTeams(cell){const src=String(cell||''),parts=[...src.matchAll(/<(?:a|span|div|p)\b[^>]*>([^<>]{2,80})<\/(?:a|span|div|p)>/gi)].map(m=>ngpPlain(m[1])).filter(x=>x&&!/^[-\d\s:.+\/]+$/.test(x));if(parts.length>=2)return[parts[0],parts[1]];const t=ngpPlain(src).split('|').map(clean).filter(Boolean);if(t.length>=2)return[t[0],t[1]];return['','']}
function ngpCells(tr){return [...String(tr||'').matchAll(/<t[dh]\b[^>]*>([\s\S]*?)<\/t[dh]>/gi)].map(m=>m[1])}
function parseNowgoalProPage(html,ts){const rows=[];for(const tr of String(html||'').matchAll(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi)){const c=ngpCells(tr[0]);if(c.length<5)continue;let timeCell='',teamCell='',scoreCell='',ahCell='',ouCell='';for(const z of c){const q=ngpPlain(z);if(!timeCell&&/\b\d{1,2}:\d{2}\s+\d{1,2}-\d{1,2}\b/.test(q))timeCell=q;if(!scoreCell&&/^-$/.test(q))scoreCell=q;if(!ahCell&&/[+-]?(?:\d+\s+)?\d*\/?\d*\s+[+-]?\d+(?:\.\d+)?/.test(q)&&!/(?:Over|Under)/i.test(q)){const nums=q.match(/[+-]?\d+(?:\.\d+)?/g)||[];if(nums.length>=2)ahCell=q}}
  // The board columns are Date | Teams | Score | 1X2 | Asian Handicap | Over/Under.
  if(c.length>=6){teamCell=c[1];scoreCell=ngpPlain(c[2]);ahCell=ngpPlain(c[c.length-2]);ouCell=ngpPlain(c[c.length-1])}
  const t=ngpTime(timeCell||ngpPlain(c[0]),ts);if(!in24(t,ts)||scoreCell!=='-')continue;let [home,away]=ngpTeams(teamCell);if(!home||!away)continue;
  const ah=ahCell.match(/([+-]?\d+(?:\.\d+)?)\s+([+-]?(?:(?:\d+\s+)?\d+\/\d+|\d+(?:\.\d+)?))\s+([+-]?\d+(?:\.\d+)?)/),ou=ouCell.match(/([+-]?\d+(?:\.\d+)?)\s+(\d+(?:\.\d+)?)\s+([+-]?\d+(?:\.\d+)?)/);if(!ah||!ou)continue;const hOdd=dec(ah[1]),line=ngpLine(ah[2]),aOdd=dec(ah[3]),oOdd=dec(ou[1]),total=Number(ou[2]),uOdd=dec(ou[3]);if(!hOdd||!aOdd||!oOdd||!uOdd||!Number.isFinite(line)||!(total>0))continue;const r=rowBase('S48',`${norm(home)}_${norm(away)}_${t}`,t,'NowGoal Pro',home,away),b=addBook(r,'NowGoalPro');addBet(b,'AH',`Home ${line}`,hOdd);addBet(b,'AH',`Away ${-line}`,aOdd);addBet(b,'OU',`Over ${total}`,oOdd);addBet(b,'OU',`Under ${total}`,uOdd);if(validRow(r))rows.push(r)}return mergeRows(rows)}
async function sourceNowgoalPro(ts){return cached('S48',ts,async()=>parseNowgoalProPage(await getText(NOWGOALPRO_BASE,{headers:{accept:'text/html,*/*','accept-language':'vi,en;q=0.8',referer:NOWGOALPRO_BASE}},6500),ts))}


// HKJC Hong Kong: public GraphQL football feed. HDC is the two-way handicap pool;
// HIL is Hi/Lo (full-time total). We use only the line explicitly flagged `main` when
// HKJC supplies it. This avoids treating HHA (three-way handicap) or CHL/FHL period/corner
// pools as Asian Handicap / full-time totals.
const HKJC_GQL='https://info.cld.hkjc.com/graphql/base/';
const HKJC_REF='https://bet.hkjc.com/ch/football/home';
const HKJC_QUERY=`query matchList($startDate:String,$endDate:String,$matchIds:[String],$tournIds:[String],$fbOddsTypes:[FBOddsType]!,$fbOddsTypesM:[FBOddsType]!,$inplayOnly:Boolean,$featuredMatchesOnly:Boolean,$frontEndIds:[String],$earlySettlementOnly:Boolean,$showAllMatch:Boolean){matches(startDate:$startDate,endDate:$endDate,matchIds:$matchIds,tournIds:$tournIds,fbOddsTypes:$fbOddsTypesM,inplayOnly:$inplayOnly,featuredMatchesOnly:$featuredMatchesOnly,frontEndIds:$frontEndIds,earlySettlementOnly:$earlySettlementOnly,showAllMatch:$showAllMatch){id frontEndId matchDate kickOffTime status homeTeam{id name_en name_ch} awayTeam{id name_en name_ch} tournament{id code name_en name_ch} foPools(fbOddsTypes:$fbOddsTypes){id status oddsType inplay name_en updateAt lines{lineId status condition main combinations{combId str status currentOdds selections{selId str name_en name_ch}}}}}}}`;
function hkjcSide(combo,home,away,kind){const c=clean(combo?.str).toUpperCase(),names=(combo?.selections||[]).map(x=>clean(x?.name_en||x?.name_ch||x?.str));if(kind==='AH'){if(c==='H'||/_H$/.test(c)||/HOME/.test(c)||names.some(x=>nameScore(x,home)>=.88))return'home';if(c==='A'||/_A$/.test(c)||/AWAY/.test(c)||names.some(x=>nameScore(x,away)>=.88))return'away'}else{if(c==='H'||/_H$/.test(c)||/HIGH|OVER/.test(c)||names.some(x=>/high|over|大/i.test(x)))return'over';if(c==='L'||/_L$/.test(c)||/LOW|UNDER/.test(c)||names.some(x=>/low|under|細|小/i.test(x)))return'under'}return''}
function hkjcLineCandidate(pool,home,away,kind){let arr=[];for(const line of pool?.lines||[]){const ln=lineFrom(line?.condition);if(!Number.isFinite(ln))continue;let left=null,right=null;for(const combo of line?.combinations||[]){const odd=dec(combo?.currentOdds);if(!odd)continue;const side=hkjcSide(combo,home,away,kind);if(side==='home'||side==='over')left=odd;else if(side==='away'||side==='under')right=odd}if(left&&right)arr.push({line:ln,left,right,main:line?.main===true,imb:Math.abs(Math.log(left/right))})}if(!arr.length)return null;const mains=arr.filter(x=>x.main);const use=mains.length?mains:arr;use.sort((a,b)=>a.imb-b.imb||Math.abs(a.line)-Math.abs(b.line));return use[0]}
function parseHKJCPayload(payload,ts){const matches=payload?.data?.matches||payload?.matches||[],rows=[];for(const m of matches){const home=clean(m?.homeTeam?.name_en||m?.homeTeam?.name_ch),away=clean(m?.awayTeam?.name_en||m?.awayTeam?.name_ch),t=parseTs(m?.kickOffTime)||parseTs(m?.matchDate),st=clean(m?.status).toLowerCase();if(!home||!away||!in24(t,ts)||/inplay|running|live|finished|closed|result/.test(st))continue;let ah=null,ou=null;for(const pool of m?.foPools||[]){if(pool?.inplay===true)continue;const typ=clean(pool?.oddsType).toUpperCase();if(typ==='HDC')ah=hkjcLineCandidate(pool,home,away,'AH')||ah;else if(typ==='HIL')ou=hkjcLineCandidate(pool,home,away,'OU')||ou}if(!ah||!ou)continue;const r=rowBase('S49',clean(m?.id||m?.frontEndId)||`${norm(home)}_${norm(away)}_${t}`,t,clean(m?.tournament?.name_en||m?.tournament?.name_ch||'HKJC Football'),home,away),b=addBook(r,'HKJC');addBet(b,'AH',`Home ${ah.line}`,ah.left);addBet(b,'AH',`Away ${-ah.line}`,ah.right);addBet(b,'OU',`Over ${ou.line}`,ou.left);addBet(b,'OU',`Under ${ou.line}`,ou.right);if(validRow(r))rows.push(r)}return mergeRows(rows)}
async function sourceHKJC(ts){return cached('S49',ts,async()=>{const start=new Date(ts).toISOString(),end=new Date(ts+86400000).toISOString(),body={query:HKJC_QUERY,variables:{startDate:start,endDate:end,matchIds:null,tournIds:null,fbOddsTypes:['HDC','HIL'],fbOddsTypesM:['HDC','HIL'],inplayOnly:false,featuredMatchesOnly:false,frontEndIds:null,earlySettlementOnly:false,showAllMatch:false}},j=await getJ(HKJC_GQL,{method:'POST',headers:{'content-type':'application/json',accept:'application/json','accept-language':'zh-HK,zh;q=0.9,en;q=0.8',origin:'https://bet.hkjc.com',referer:HKJC_REF},body:JSON.stringify(body)},8500);if(j?.errors?.length)throw new Error(`HKJC GraphQL: ${clean(j.errors[0]?.message||'error')}`);return parseHKJCPayload(j,ts)})}



// Tipsme Hong Kong: public odds-trend page + per-match odds pages. The match page
// exposes separate bookmaker rows for current/close Asian Handicap and Total O/U.
// We preserve bookmaker identities and only use the CLOSE columns; open lines are
// never substituted as current lines.
const TIPSME_BASE='https://tipsme.hk';
function tipsDecode(v){return clean(String(v??'').replace(/&nbsp;|&#160;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'"').replace(/&#39;|&apos;/gi,"'").replace(/&minus;|&#8722;|&ndash;|&#8211;|&mdash;|&#8212;/gi,'-').replace(/&lt;/gi,'<').replace(/&gt;/gi,'>'))}
function tipsPlain(html){return tipsDecode(String(html||'').replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi,' ').replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi,' ').replace(/<br\s*\/?>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' '))}
function tipsCells(row){return [...String(row||'').matchAll(/<t[dh]\b[^>]*>([\s\S]*?)<\/t[dh]>/gi)].map(m=>tipsPlain(m[1]))}
function tipsDiscover(html){const out=[],seen=new Set();for(const m of String(html||'').matchAll(/href=["']([^"']*\/en\/match\/(\d+)\/(?:chat|odds|stats|live)[^"']*)["']/gi)){const id=m[2];if(seen.has(id))continue;seen.add(id);out.push({id,href:`/en/match/${id}/odds`})}return out}
function tipsDateTime(text){let iso=String(text||'').match(/20\d\d-\d\d-\d\dT\d\d:\d\d(?::\d\d(?:\.\d+)?)?Z/);if(iso)return parseTs(iso[0]);const m=String(text||'').match(/(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2}),\s*(20\d{2})\s+(\d{1,2}):(\d{2})\s*(AM|PM)/i);if(!m)return null;let h=Number(m[4])%12;if(/PM/i.test(m[6]))h+=12;return Date.UTC(Number(m[3]),['january','february','march','april','may','june','july','august','september','october','november','december'].indexOf(m[1].toLowerCase()),Number(m[2]),h,Number(m[5]))}
function tipsMeta(html){const src=String(html||''),text=tipsPlain(src);let home='',away='',league='Tipsme Football';const h1=tipsPlain((src.match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i)||[])[1]||'');let m=(h1||text).match(/^\s*(.{2,100}?)\s+vs\s*(.{2,100}?)\s*[·•]/i);if(!m)m=(h1||text).match(/(.{2,100}?)\s+vs\s*(.{2,100}?)\s*(?:·|Football Betting)/i);if(m){home=clean(m[1]);away=clean(m[2])}const at=h1?text.indexOf(h1):-1,rest=at>=0?text.slice(at+h1.length):text,lm=rest.match(/^\s*([A-Za-z0-9 .&'()\/-]{2,80})\s*[·•]\s*(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},\s*20\d{2}/i);if(lm)league=clean(lm[1]);return{home,away,league,t:tipsDateTime(src)||tipsDateTime(text),text}}
function tipsSection(html,start,stop){const low=String(html||'').toLowerCase(),i=low.indexOf(String(start).toLowerCase());if(i<0)return'';const j=low.indexOf(String(stop).toLowerCase(),i+start.length);return String(html).slice(i,j>=0?j:undefined)}
function tipsDec(v){const n=num(v);return n!==null&&n>0&&n<5?1+n:null}
function tipsBookLabel(name){const x=clean(name);if(/^365$/i.test(x))return'Bet365';if(/^1x\*?$/i.test(x))return'1xBet';if(/^bwin$/i.test(x))return'Bwin';return x}
function tipsBook(r,name){const n=tipsBookLabel(name),id=bookId(n);if(!n||!id||/^(min|max|company)$/i.test(n))return null;let b=(r?.od?.[0]?.bookmakers||[]).find(x=>bookId(x.name)===id);return b||addBook(r,n)}
function tipsHKDec(v){const n=Number(clean(v));return Number.isFinite(n)&&n>0&&n<10?+(n+1).toFixed(4):null}
function parseTipsmePage(html,id,ts){const meta=tipsMeta(html);if(!meta.home||!meta.away||!in24(meta.t,ts))return null;const ahSec=tipsSection(html,'Asian Handicap Football Odds Changes','Total over/under Football Odds Changes'),ouSec=tipsSection(html,'Total over/under Football Odds Changes','1X2 Football Odds Changes');if(!ahSec||!ouSec)return null;const r=rowBase('S50',id||`${norm(meta.home)}_${norm(meta.away)}_${meta.t}`,meta.t,meta.league,meta.home,meta.away);
 for(const tr of ahSec.matchAll(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi)){const c=tipsCells(tr[0]);if(c.length<7)continue;const b=tipsBook(r,c[0]),hl=lineFrom(c[5]),ho=tipsDec(c[4]),ao=tipsDec(c[6]);if(!b||!Number.isFinite(hl)||!ho||!ao)continue;addBet(b,'AH',`Home ${hl}`,ho);addBet(b,'AH',`Away ${-hl}`,ao)}
 for(const tr of ouSec.matchAll(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi)){const c=tipsCells(tr[0]);if(c.length<7)continue;const b=tipsBook(r,c[0]),line=lineFrom(c[5]),oo=tipsDec(c[4]),uo=tipsDec(c[6]);if(!b||!(line>0)||!oo||!uo)continue;addBet(b,'OU',`Over ${line}`,oo);addBet(b,'OU',`Under ${line}`,uo)}
 return validRow(r)?r:null}
async function sourceTipsme(ts){return cached('S50',ts,async()=>{const hdr={accept:'text/html,*/*',referer:`${TIPSME_BASE}/en`,'accept-language':'en-HK,en;q=0.9'},events=[];for(const u of [`${TIPSME_BASE}/en/odds`,`${TIPSME_BASE}/en`]){try{const h=await getText(u,{headers:hdr},5000);for(const e of tipsDiscover(h))if(!events.some(x=>x.id===e.id))events.push(e)}catch{}}const rows=await poolMap(events.slice(0,36),9,async e=>{try{return parseTipsmePage(await getText(`${TIPSME_BASE}${e.href}`,{headers:hdr},4300),e.id,ts)}catch{return null}});return mergeRows(rows.filter(Boolean))})}

// SportyBet Nigeria: anonymous web-client prematch feed. Strict Sportradar market ids only:
// 16 = full-match Asian Handicap (1714 home/+hcp, 1715 away/-hcp)
// 18 = full-match Total (12 over, 13 under). Market 14 is European 3-way handicap and is rejected.
const SPORTYBET_BASE='https://www.sportybet.com/api/ng/factsCenter';
